INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'souq-naqel-case-1', 'National Day Flash Sale 4,200 Orders', 'موسم تخفيضات اليوم الوطني 4200 طلب', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Tubli with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Tubli وفق أعلى معايير الجودة والالتزام.', 50, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://souqalbahrain.bh/work/souq-naqel-case-1', 'Tubli, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'souq-naqel-2026-outlook', 'Souq Al-Bahrain 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — سوق البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from Souq Al-Bahrain in Tubli.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سوق البحرين في Tubli.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics. Focusing on Smart Home Setup & Wi-Fi Mesh, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع. من خلال خدمة تركيب المنزل الذكي وشبكات الواي فاي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics.</p><p>Focusing on <strong>Smart Home Setup & Wi-Fi Mesh</strong>, our Tubli specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع.</p><p>من خلال خدمة <strong>تركيب المنزل الذكي وشبكات الواي فاي</strong>، يعمل فريقنا في Tubli على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Souq Al-Bahrain 2026 GCC Market Outlook & Benchmarks | Souq Al-Bahrain', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — سوق البحرين | سوق البحرين', 'Executive guide by Souq Al-Bahrain covering Smart Home Setup & Wi-Fi Mesh benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير تركيب المنزل الذكي وشبكات الواي فاي في البحرين.', 'Insights', '{"online_store","insights","Tubli","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Souq Al-Bahrain initiate a Smart Home Setup & Wi-Fi Mesh engagement?', 'كم يستغرق بدء تنفيذ خدمة تركيب المنزل الذكي وشبكات الواي فاي لدى سوق البحرين؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Tubli.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Tubli.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'souq-naqel-case-2', 'BenefitPay One-Tap Checkout Lift (+34%)', 'زيادة إتمام الشراء بالدفع السريع +34%', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Tubli with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Tubli وفق أعلى معايير الجودة والالتزام.', 10.5, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://souqalbahrain.bh/work/souq-naqel-case-2', 'Tubli, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'souq-naqel-service-standards', 'Inside Our Tech Care SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في تركيب المنزل الذكي وشبكات الواي فاي', 'Key operational benchmarks, real metrics, and 2026 guidance from Souq Al-Bahrain in Tubli.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سوق البحرين في Tubli.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics. Focusing on 2-Hour Same-Day Manama Express Delivery, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع. من خلال خدمة توصيل فوري خلال ساعتين في المنامة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics.</p><p>Focusing on <strong>2-Hour Same-Day Manama Express Delivery</strong>, our Tubli specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع.</p><p>من خلال خدمة <strong>توصيل فوري خلال ساعتين في المنامة</strong>، يعمل فريقنا في Tubli على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Tech Care SLA: Speed, Quality & Auditability | Souq Al-Bahrain', 'معايير اتفاقية مستوى الخدمة والجودة في تركيب المنزل الذكي وشبكات الواي فاي | سوق البحرين', 'Executive guide by Souq Al-Bahrain covering 2-Hour Same-Day Manama Express Delivery benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير توصيل فوري خلال ساعتين في المنامة في البحرين.', 'Operations', '{"online_store","operations","Tubli","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-158901-1 and VAT ID 200015890100002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-158901-1 والرقم الضريبي 200015890100002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-3', 'pcat-cms-3', 'souq-naqel-case-3', 'GCC Same-Week Cross-Border Store Launch', 'توسع الشحن الأسبوعي الموحد لدول الخليج', 'Dilmun Energy Partners', 2025, 'Delivered for Dilmun Energy Partners across Tubli with measurable SLA benchmarks.', 'تم التنفيذ لصالح شركاء دلمون للطاقة في Tubli وفق أعلى معايير الجودة والالتزام.', 2.5, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://souqalbahrain.bh/work/souq-naqel-case-3', 'Tubli, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'souq-naqel-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from Souq Al-Bahrain in Tubli.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سوق البحرين في Tubli.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics. Focusing on Luxury Ribbons & Handwritten Gift Note, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع. من خلال خدمة تغليف هدايا فاخر مع بطاقة تهنئة مكتوبة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics.</p><p>Focusing on <strong>Luxury Ribbons & Handwritten Gift Note</strong>, our Tubli specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع.</p><p>من خلال خدمة <strong>تغليف هدايا فاخر مع بطاقة تهنئة مكتوبة</strong>، يعمل فريقنا في Tubli على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | Souq Al-Bahrain', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | سوق البحرين', 'Executive guide by Souq Al-Bahrain covering Luxury Ribbons & Handwritten Gift Note benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير تغليف هدايا فاخر مع بطاقة تهنئة مكتوبة في البحرين.', 'Governance', '{"online_store","governance","Tubli","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '18 days', true, now() - interval '18 days', now()) ON CONFLICT (id) DO NOTHING;
