INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-8', 'souq-naqel-safety-and-compliance', 'Protecting Client Data & Operational Continuity Year-Round', 'حماية بيانات العملاء واستمرارية الأعمال على مدار العام', 'Key operational benchmarks, real metrics, and 2026 guidance from Souq Al-Bahrain in Tubli.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سوق البحرين في Tubli.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics. Focusing on Cross-Border DHL Express GCC Fulfillment, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع. من خلال خدمة شحن دولي سريع لدول مجلس التعاون الخليجي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics.</p><p>Focusing on <strong>Cross-Border DHL Express GCC Fulfillment</strong>, our Tubli specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع.</p><p>من خلال خدمة <strong>شحن دولي سريع لدول مجلس التعاون الخليجي</strong>، يعمل فريقنا في Tubli على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Protecting Client Data & Operational Continuity Year-Round | Souq Al-Bahrain', 'حماية بيانات العملاء واستمرارية الأعمال على مدار العام | سوق البحرين', 'Executive guide by Souq Al-Bahrain covering Cross-Border DHL Express GCC Fulfillment benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير شحن دولي سريع لدول مجلس التعاون الخليجي في البحرين.', 'Compliance', '{"online_store","compliance","Tubli","2026"}'::text[], 'Bader Ali', 'published', now() - interval '48 days', false, now() - interval '48 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-8', 'Are all deliverables, contracts, and portals available in Arabic and English?', 'هل تتوفر المخرجات والعقود والبوابة باللغتين العربية والإنجليزية؟', 'Every contract, invoice, report, and support interaction is natively bilingual across Arabic and English.', 'جميع العقود والفواتير والتقارير والتفاعلات مصممة ثنائية اللغة أصالةً باللغتين العربية والإنجليزية.', 'bilingual', true, 8, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
